import org.junit.runner.*; public class UiMethods { public static void main(String[] args) throws Exception { JUnitCore core=new JUnitCore(); core.addListener(new org.junit.internal.TextListener(System.out)); int total=0, failed=0; for(String arg:args){System.out.println("CASE "+arg);String[] p=arg.split("#",2);Result r=core.run(Request.method(Class.forName(p[0]),p[1]));total+=r.getRunCount();failed+=r.getFailureCount();}System.out.println("TOTAL tests="+total+" failures="+failed);System.exit(failed==0?0:1); } }
